  "type": "hysteria2",
  "server": "server.example.com",
  "server_port": 443,
  // \u7AEF\u53E3\u8DF3\u8DC3\uFF08\u53EF\u9009\uFF09\uFF1A\u586B\u4E86 server_ports \u540E server_port \u4F1A\u88AB\u5FFD\u7565
  // "server_ports": ["20000:50000"],
  // "hop_interval": "30s",
  "up_mbps": 50,
  "down_mbps": 300,
  "password": "",
  // \u6DF7\u6DC6\uFF08\u53EF\u9009\uFF0C\u9700\u4E0E\u670D\u52A1\u7AEF\u4E00\u81F4\uFF09
